import React, { useEffect, useMemo, useRef, useState } from 'react';
import { io } from 'socket.io-client';
import { useNavigate } from 'react-router-dom';
import { api, normalizeTrades, badgeClass } from '../services/api';

const SOCKET_URL = 'http://localhost:5000';

function formatTime(ts) {
  if (!ts) return '—';
  try {
    return new Date(ts).toLocaleString();
  } catch {
    return ts;
  }
}

function TrendChart({ logs }) {
  const canvasRef = useRef(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    const width = canvas.offsetWidth || 520;
    const height = 280;
    canvas.width = width * 2;
    canvas.height = height * 2;
    canvas.style.height = `${height}px`;

    const ctx = canvas.getContext('2d');
    ctx.scale(2, 2);
    ctx.clearRect(0, 0, width, height);

    const data = [...(logs || [])]
      .slice(0, 20)
      .reverse()
      .map((log, idx) => ({
        x: idx + 1,
        y: Number(log?.risk_score || 0),
      }));

    const padL = 46;
    const padR = 18;
    const padT = 20;
    const padB = 40;
    const chartW = width - padL - padR;
    const chartH = height - padT - padB;

    const bg = ctx.createLinearGradient(0, 0, 0, height);
    bg.addColorStop(0, 'rgba(35,255,119,0.05)');
    bg.addColorStop(1, 'rgba(35,255,119,0.00)');
    ctx.fillStyle = bg;
    ctx.fillRect(padL, padT, chartW, chartH);

    ctx.strokeStyle = 'rgba(255,255,255,0.08)';
    ctx.lineWidth = 1;
    for (let y = 0; y <= 100; y += 20) {
      const py = padT + chartH - (y / 100) * chartH;
      ctx.beginPath();
      ctx.moveTo(padL, py);
      ctx.lineTo(width - padR, py);
      ctx.stroke();
      ctx.fillStyle = '#6e8376';
      ctx.font = '11px Inter';
      ctx.fillText(String(y), 16, py + 4);
    }

    ctx.strokeStyle = 'rgba(255,255,255,0.16)';
    ctx.beginPath();
    ctx.moveTo(padL, padT);
    ctx.lineTo(padL, padT + chartH);
    ctx.lineTo(width - padR, padT + chartH);
    ctx.stroke();

    if (!data.length) {
      ctx.fillStyle = '#6c7a71';
      ctx.font = '12px Inter';
      ctx.fillText('No suspicious non-loop risk events yet', padL + 12, padT + chartH / 2);
      return;
    }

    const points = data.map((d, i) => ({
      x: padL + (i / Math.max(data.length - 1, 1)) * chartW,
      y: padT + chartH - (d.y / 100) * chartH,
      raw: d.y,
      label: d.x,
    }));

    ctx.beginPath();
    points.forEach((p, i) => {
      if (i === 0) ctx.moveTo(p.x, p.y);
      else ctx.lineTo(p.x, p.y);
    });
    ctx.strokeStyle = '#6dff9f';
    ctx.lineWidth = 3;
    ctx.shadowColor = 'rgba(109,255,159,0.18)';
    ctx.shadowBlur = 12;
    ctx.stroke();
    ctx.shadowBlur = 0;

    points.forEach((p, i) => {
      ctx.beginPath();
      ctx.arc(p.x, p.y, 4, 0, Math.PI * 2);
      ctx.fillStyle =
        p.raw >= 70 ? '#93ff73' : p.raw >= 40 ? '#72ffab' : '#4da56d';
      ctx.fill();

      if (i % 2 === 0 || points.length <= 8) {
        ctx.fillStyle = '#74877d';
        ctx.font = '10px Inter';
        ctx.fillText(String(p.label), p.x - 3, padT + chartH + 16);
      }
    });
  }, [logs]);

  return <canvas ref={canvasRef} style={{ width: '100%', display: 'block' }} />;
}

function Panel({ title, subtitle, right, children }) {
  return (
    <div
      style={{
        overflow: 'hidden',
        borderRadius: 22,
        background: 'linear-gradient(180deg, rgba(7,24,15,0.94), rgba(0,0,0,0.98))',
        border: '1px solid rgba(101,255,151,0.08)',
        boxShadow: 'inset 0 1px 0 rgba(255,255,255,0.02), 0 18px 48px rgba(0,0,0,0.36)',
        backdropFilter: 'blur(18px)',
        WebkitBackdropFilter: 'blur(18px)',
      }}
    >
      <div
        style={{
          padding: '18px 20px',
          borderBottom: '1px solid rgba(255,255,255,0.05)',
          display: 'flex',
          justifyContent: 'space-between',
          gap: 12,
          alignItems: 'center',
        }}
      >
        <div>
          <div style={{ fontSize: 17, fontWeight: 900, color: '#edfff2' }}>{title}</div>
          {subtitle ? (
            <div style={{ color: '#708478', fontSize: 12, marginTop: 6 }}>{subtitle}</div>
          ) : null}
        </div>
        {right}
      </div>
      {children}
    </div>
  );
}

function StatCard({ label, value, sub }) {
  return (
    <div
      style={{
        padding: 20,
        borderRadius: 20,
        background: 'linear-gradient(180deg, rgba(7,24,15,0.94), rgba(0,0,0,0.98))',
        border: '1px solid rgba(101,255,151,0.08)',
        boxShadow: 'inset 0 1px 0 rgba(255,255,255,0.02), 0 14px 40px rgba(0,0,0,0.35)',
      }}
    >
      <div style={{ color: '#789080', fontSize: 12, fontWeight: 800, letterSpacing: '0.08em', textTransform: 'uppercase' }}>
        {label}
      </div>
      <div style={{ color: '#77ffad', fontSize: 38, fontWeight: 900, marginTop: 12 }}>
        {value}
      </div>
      <div style={{ color: '#5f7368', fontSize: 13, marginTop: 8 }}>{sub}</div>
    </div>
  );
}

export default function DashboardPage() {
  const navigate = useNavigate();

  const [stats, setStats] = useState({});
  const [trades, setTrades] = useState([]);
  const [riskLogs, setRiskLogs] = useState([]);
  const [cycles, setCycles] = useState([]);

  const loadAll = async () => {
    try {
      const [statsRes, tradesRes, riskRes, cycleRes] = await Promise.all([
        api.fetchStats(),
        api.fetchTrades(1, 50),
        api.fetchFraudLogs(),
        api.fetchFraudCycles(),
      ]);

      setStats(statsRes || {});
      setRiskLogs(riskRes || []);
      setTrades(normalizeTrades(tradesRes || [], riskRes || []));
      setCycles(cycleRes || []);
    } catch (err) {
      console.error('DashboardPage loadAll error:', err);
    }
  };

  useEffect(() => {
    loadAll();

    const intervalId = setInterval(loadAll, 2200);
    const socket = io(SOCKET_URL, { transports: ['websocket', 'polling'] });

    socket.on('fraud_alert', loadAll);
    socket.on('fraud_detected', loadAll);
    socket.on('risk_log', loadAll);
    socket.on('trade_inserted', loadAll);
    socket.on('trust_score_updated', loadAll);

    return () => {
      clearInterval(intervalId);
      socket.disconnect();
    };
  }, []);

  const computed = useMemo(() => {
    const totalTrades = Number(stats?.total_trades ?? trades.length ?? 0);
    const fraudRings = Number(stats?.fraud_rings_detected ?? cycles.length ?? 0);
    const monitored = Number(stats?.monitored_traders ?? stats?.total_traders ?? 0);
    const abnormalEntries = riskLogs.filter((log) =>
      String(log?.reason || '').toLowerCase().includes('abnormal price')
    ).length;

    return {
      totalTrades,
      fraudRings,
      monitored,
      abnormalEntries,
    };
  }, [stats, trades, cycles, riskLogs]);

  return (
    <div className="page-wrap grid-bg" style={{ background: '#000000' }}>
      <div className="page-container">
        <div style={{ marginBottom: 24 }}>
          <h1 style={{ fontSize: 30, fontWeight: 900, margin: 0, color: '#effff2' }}>
            TraceNet <span style={{ color: '#73ffad' }}>Dashboard</span>
          </h1>
          <div style={{ color: '#768b7d', marginTop: 10, fontSize: 14 }}>
            Pitch-black and dark-green fraud analytics dashboard
          </div>
        </div>

        <div className="kpi-grid" style={{ marginBottom: 18 }}>
          <StatCard label="Total Trades" value={computed.totalTrades} sub="All recorded transactions" />
          <StatCard label="Loop Groups" value={computed.fraudRings} sub="Detected circular trading loops" />
          <StatCard label="Abnormal Price Logs" value={computed.abnormalEntries} sub="Written into risk log" />
          <StatCard label="Monitored Traders" value={computed.monitored} sub="Tracked by trust system" />
        </div>

        <div className="grid-2" style={{ marginBottom: 18, alignItems: 'start' }}>
          <Panel
            title="Detected Circular Loops"
            subtitle="Loop paths are shown here, separate from the risk log"
            right={<span className="badge badge-low">{cycles.length} loops</span>}
          >
            <div className="scroll-y" style={{ maxHeight: 360 }}>
              <table className="data-table">
                <thead>
                  <tr>
                    <th>Stock</th>
                    <th>Loop Path</th>
                    <th>Trade Path</th>
                    <th>Depth</th>
                    <th>Confidence</th>
                  </tr>
                </thead>
                <tbody>
                  {cycles.slice(0, 10).map((item, idx) => (
                    <tr key={`${item.group_id || item.trade_id}-${idx}`}>
                      <td>{item.symbol || `#${item.stock_id}`}</td>
                      <td style={{ color: '#76ffaf', fontWeight: 800 }}>
                        {Array.isArray(item.cycle) ? item.cycle.join(' → ') : '—'}
                      </td>
                      <td style={{ color: '#8ea395' }}>
                        {Array.isArray(item.trade_path) ? item.trade_path.join(' → ') : '—'}
                      </td>
                      <td>{item.max_depth ?? item.depth ?? '—'}</td>
                      <td>
                        <span className={badgeClass(item.confidence || 0)}>
                          {item.confidence || 0}
                        </span>
                      </td>
                    </tr>
                  ))}
                  {!cycles.length && (
                    <tr>
                      <td colSpan="5">
                        <div className="empty-state">No loops detected yet.</div>
                      </td>
                    </tr>
                  )}
                </tbody>
              </table>
            </div>
          </Panel>

          <div style={{ display: 'grid', gap: 18 }}>
            <div
              style={{
                padding: 20,
                borderRadius: 22,
                background: 'linear-gradient(180deg, rgba(12,18,14,0.88), rgba(0,0,0,0.95))',
                border: '1px solid rgba(101,255,151,0.08)',
                boxShadow: 'inset 0 1px 0 rgba(255,255,255,0.02), 0 18px 48px rgba(0,0,0,0.36)',
              }}
            >
              <div style={{ fontSize: 16, fontWeight: 900, color: '#ecfff1', marginBottom: 6 }}>
                Suspicious Transaction Trend
              </div>
              <div style={{ color: '#708378', fontSize: 12, marginBottom: 12 }}>
                Non-loop suspicious trade scores over recent events
              </div>
              <TrendChart logs={riskLogs} />
            </div>

            <Panel title="Navigation" subtitle="Useful pages only">
              <div style={{ display: 'flex', gap: 12, padding: 18, flexWrap: 'wrap' }}>
                <button
                  className="btn-outline"
                  onClick={() => navigate('/fraud')}
                  style={{
                    background: 'rgba(9,28,17,0.88)',
                    border: '1px solid rgba(101,255,151,0.12)',
                    color: '#e3ffee',
                  }}
                >
                  Fraud Engine
                </button>
                <button
                  className="btn-outline"
                  onClick={() => navigate('/traders')}
                  style={{
                    background: 'rgba(9,28,17,0.88)',
                    border: '1px solid rgba(101,255,151,0.12)',
                    color: '#e3ffee',
                  }}
                >
                  Traders
                </button>
              </div>
            </Panel>
          </div>
        </div>

        <Panel
          title="Suspicious Transaction Risk Log"
          subtitle="Abnormal price, repeated patterns, and trust-based signals"
          right={<span className="badge badge-medium">{riskLogs.length} entries</span>}
        >
          <div className="scroll-y" style={{ maxHeight: 340 }}>
            <table className="data-table">
              <thead>
                <tr>
                  <th>Trade ID</th>
                  <th>Risk</th>
                  <th>Label</th>
                  <th>Reason</th>
                  <th>Detected</th>
                </tr>
              </thead>
              <tbody>
                {riskLogs.slice(0, 20).map((log, idx) => (
                  <tr key={`${log.risk_id || log.trade_id}-${idx}`}>
                    <td>#{log.trade_id}</td>
                    <td>{log.risk_score}</td>
                    <td>
                      <span className={badgeClass(log.risk_score)}>
                        {log.risk_label || 'SUSPICIOUS'}
                      </span>
                    </td>
                    <td style={{ maxWidth: 650 }}>{log.reason}</td>
                    <td>{formatTime(log.detected_at)}</td>
                  </tr>
                ))}
                {!riskLogs.length && (
                  <tr>
                    <td colSpan="5">
                      <div className="empty-state">No suspicious non-loop log entries yet.</div>
                    </td>
                  </tr>
                )}
              </tbody>
            </table>
          </div>
        </Panel>
      </div>
    </div>
  );
}
